<?php
namespace App\Http\Controllers;
use App\Models\Agenda;
use Illuminate\Http\Request;
class AgendaController extends Controller { public function index(Request $r){$q=$r->string('q');$data=Agenda::when($q,fn($x)=>$x->where('kegiatan','like',"%$q%")->orWhere('tempat','like',"%$q%"))->orderByDesc('tanggal')->paginate(15)->withQueryString();return view('agenda.index',compact('data','q'));} public function create(){return view('agenda.form',['item'=>new Agenda]);} public function store(Request $r){$d=$r->validate(['tanggal'=>'required|date','waktu'=>'nullable','kegiatan'=>'required','tempat'=>'nullable','penanggung_jawab'=>'nullable','keterangan'=>'nullable']);Agenda::create($d);return redirect()->route('agenda.index')->with('success','Agenda berhasil disimpan.');} public function edit(Agenda $agenda){return view('agenda.form',['item'=>$agenda]);} public function update(Request $r,Agenda $agenda){$d=$r->validate(['tanggal'=>'required|date','waktu'=>'nullable','kegiatan'=>'required','tempat'=>'nullable','penanggung_jawab'=>'nullable','keterangan'=>'nullable']);$agenda->update($d);return redirect()->route('agenda.index')->with('success','Agenda diperbarui.');} public function destroy(Agenda $agenda){$agenda->delete();return back()->with('success','Agenda dihapus.');} }
